    expect(removed.decision.ruleIds).toContain("media_sticker");
    expect(removed.decision.evidence).toEqual([
      { kind: "feature", summary: "media:sticker" },
    ]);
    expect(moderator.deleted.map((item) => item.messageId)).toEqual(["650"]);
